Running command: cd /workspace/repo-vul/src-vul/openthread && cat > /tmp/print_addrs.cpp << 'EOF'
#include <stdio.h>
#include <openthread/instance.h>
#include <openthread/ip6.h>
#include <openthread/link.h>
#include <openthread/thread.h>
#include <openthread/thread_ftd.h>
#include <openthread/types.h>

int main() {
    const otPanId panId = 0xdead;
    otInstance *sInstance = otInstanceInitSingle();
    otLinkSetPanId(sInstance, panId);
    otIp6SetEnabled(sInstance, true);
    otThreadSetEnabled(sInstance, true);
    otThreadBecomeLeader(sInstance);

    const otNetifAddress *addr = otIp6GetUnicastAddresses(sInstance);
    while (addr) {
        char buf[64];
        otIp6AddressToString(&addr->mAddress, buf, sizeof(buf));
        printf("addr: %s prefix_len=%d\n", buf, addr->mPrefixLength);
        addr = addr->mNext;
    }
    printf("rloc16: %04x\n", otThreadGetRloc16(sInstance));
    return 0;
}
EOF
echo "written"

